interface Notice { String text(); }
class ExamNotice implements Notice {
    @Override
    public String text() { return "Exam"; }
}
class LabNotice implements Notice {
    @Override
    public String text() { return "Lab"; }
}
final class NoticeFactory {
    private NoticeFactory() { }
    static Notice create(int kind) {
        if (kind == 0) { return new ExamNotice(); }
        return new LabNotice();
    }
}

class Main {
    public static void main(String[] args) {
        Notice notice = NoticeFactory.create(1);
        System.out.println(notice.text());
    }
}

interface Rate { int fare(int distance); }
class RegularRate implements Rate {
    @Override
    public int fare(int distance) { return distance * 4; }
}
class ReducedRate implements Rate {
    @Override
    public int fare(int distance) { return distance * 2; }
}
class Ticket {
    private final Rate rate;
    Ticket(Rate rate) { this.rate = rate; }
    int fare(int distance) { return rate.fare(distance); }
}

class Main {
    public static void main(String[] args) {
        Ticket ticket = new Ticket(new ReducedRate());
        System.out.println(ticket.fare(7));
    }
}

interface Listener { void changed(int seats); }
class Display implements Listener {
    private final String name;
    Display(String name) { this.name = name; }
    @Override
    public void changed(int seats) { System.out.println(name + " " + seats); }
}
class SeatBoard {
    private final Listener[] listeners = new Listener[2];
    private int size;
    boolean subscribe(Listener listener) {
        if (listener == null || size == listeners.length) { return false; }
        listeners[size++] = listener;
        return true;
    }
    void publish(int seats) {
        for (int i = 0; i < size; i++) { listeners[i].changed(seats); }
    }
}

class Main {
    public static void main(String[] args) {
        SeatBoard board = new SeatBoard();
        board.subscribe(new Display("A"));
        board.subscribe(new Display("B"));
        board.publish(3);
    }
}
